  if (!HOST_TEMPLATE_MAP.hasOwnProperty(host)) continue;

  var tplKey = HOST_TEMPLATE_MAP[host];
  var tpl = TEMPLATES[tplKey];

  hosts.push(host)

  if (tpl) {
    var copy = {};
