        copy[k] = tpl[k];
      }
    }
    rules[host] = copy;
  }
}

// ===== 加解密函数 =====
function textEncrypt(text) {
    let passwd = "lzxHpH8PLGXcrCIQ";
    let key = passwd.padEnd(32, "\0");
    let iv = passwd.padEnd(16, "\0");

    let cipher = this.java.createSymmetricCrypto(
            "aes/cbc/pkcs7padding",
            key,
            iv
        )
        .encryptBase64(text);

    return encodeURIComponent(cipher);
}

function dataEncrypt(body) {
    const {java, cache} = this;

    let keys = cache.get(GET.call(this, 'server'));

    let data = JSON.parse(keys);
    const { secretKey, ivKey } = data;

    java.log(secretKey + '   ' + ivKey);

    let key = java.strToBytes(secretKey);
    let iv = java.strToBytes(ivKey);

    let cipher = java.createSymmetricCrypto(
            "aes/cbc/pkcs7padding",
            key,
            iv
        )
        .encryptBase64(body);

    return encodeURIComponent(cipher);
}

function toSearch() {
  const {java, source, cache} = this;
  source.refreshExplore();
  let k = cache.getFromMemory('searchk');
  java.searchBook(k, source);
}

function checkKey(kw) {
    var java = this.java;
    if (!kw || kw.length < 2) {
        java.longToast('请输入至少2个字符');
        return false;
    }
    if (kw.length > 8) {
        java.longToast('搜索词不能超过8个字符');
        return false;
    }
    if (!/^[\u4e00-\u9fa5A-Za-z0-9]+$/.test(kw)) {
        java.longToast('仅支持汉字、字母、数字，禁止符号');
        return false;
    }
    return true;
}

// ===== 工具函数 =====
function GET(k) {
  const { java, source } = this;
  var d = {};
  try { d = JSON.parse(source.getVariable() || "{}"); } catch (e) { d = {}; }
  return d[k] || '';
}

function SET(k, v) {
  const { java, source } = this;
  var d = {};
  try { d = JSON.parse(source.getVariable() || "{}"); } catch (e) { d = {}; }
  d[k] = v;
  source.putVariable(JSON.stringify(d, null, '\t'));
}


function began() {
